import { PatternFrame, type PatternProps } from "./frame"
import { on, Run } from "./motion"

// Interpolation in latent space: the path sweeps from A to B and back,
// and each sample on it fills as the sweep passes. Positions run along
// A to B (211.81) and back.
const L = 211.81
const sweep = { w: 20, p: 2 * L }

const sample = (cx: number, cy: number, at: number) => (
  <>
    <circle
      cx={cx}
      cy={cy}
      r="6"
      fill="var(--ds-background-100)"
      stroke="currentColor"
    />
    <circle
      cx={cx}
      cy={cy}
      r="6"
      fill="currentColor"
      stroke="currentColor"
      {...on(sweep, at, 6)}
    />
    <circle
      cx={cx}
      cy={cy}
      r="6"
      fill="currentColor"
      stroke="currentColor"
      {...on(sweep, 2 * L - at, 6)}
    />
  </>
)

